95	interface GetCorrectedFileContentResult {
96	  originalContent: string;
97	  correctedContent: string;
98	  fileExists: boolean;
99	  error?: { message: string; code?: string };
100	}
101	
102	export async function getCorrectedFileContent(
103	  config: Config,
104	  filePath: string,
105	  proposedContent: string,
106	  abortSignal: AbortSignal,
107	): Promise<GetCorrectedFileContentResult> {
108	  let originalContent = '';
109	  let fileExists = false;
110	  let correctedContent = proposedContent;
111	
112	  try {
113	    originalContent = await config
114	      .getFileSystemService()
115	      .readTextFile(filePath);
116	    fileExists = true; // File exists and was read
117	  } catch (err) {
118	    if (isNodeError(err) && err.code === 'ENOENT') {
119	      fileExists = false;
120	      originalContent = '';
121	    } else {
122	      // File exists but could not be read (permissions, etc.)
123	      fileExists = true; // Mark as existing but problematic
124	      originalContent = ''; // Can't use its content
125	      const error = {
126	        message: getErrorMessage(err),
127	        code: isNodeError(err) ? err.code : undefined,
128	      };
129	      // Return early as we can't proceed with content correction meaningfully
130	      return { originalContent, correctedContent, fileExists, error };
131	    }
132	  }
133	
134	  const aggressiveUnescape = !isGemini3Model(config.getActiveModel());
135	
136	  correctedContent = await ensureCorrectFileContent(
137	    proposedContent,
138	    config.getBaseLlmClient(),
139	    abortSignal,
140	    config.getDisableLLMCorrection(),
141	    aggressiveUnescape,
142	  );
143	
144	  return { originalContent, correctedContent, fileExists };
145	}
