25	/**
26	 * Resolves a plan file path and strictly validates it against the plans directory boundary.
27	 * Useful for tools that need to write or read plans.
28	 * @param planPath The untrusted file path provided by the model.
29	 * @param plansDir The authorized project plans directory.
30	 * @returns The safely resolved path string.
31	 * @throws Error if the path is empty, malicious, or escapes boundaries.
32	 */
33	export function resolveAndValidatePlanPath(
34	  planPath: string,
35	  plansDir: string,
36	  projectRoot: string,
37	): string {
38	  const trimmedPath = planPath.trim();
39	  if (!trimmedPath) {
40	    throw new Error('Plan file path must be non-empty.');
41	  }
42	
43	  // 1. Handle case where agent provided an absolute path
44	  if (path.isAbsolute(trimmedPath)) {
45	    if (
46	      isSubpath(resolveToRealPath(plansDir), resolveToRealPath(trimmedPath))
47	    ) {
48	      return trimmedPath;
49	    }
50	  }
51	
52	  // 2. Handle case where agent provided a path relative to the project root
53	  const resolvedFromProjectRoot = path.resolve(projectRoot, trimmedPath);
54	  if (
55	    isSubpath(
56	      resolveToRealPath(plansDir),
57	      resolveToRealPath(resolvedFromProjectRoot),
58	    )
59	  ) {
60	    return resolvedFromProjectRoot;
61	  }
62	
63	  // 3. Handle default case where agent provided a path relative to the plans directory
64	  const resolvedPath = path.resolve(plansDir, trimmedPath);
65	  const realPath = resolveToRealPath(resolvedPath);
66	  const realPlansDir = resolveToRealPath(plansDir);
67	
68	  if (!isSubpath(realPlansDir, realPath)) {
69	    throw new Error(
70	      PlanErrorMessages.PATH_ACCESS_DENIED(trimmedPath, plansDir),
71	    );
72	  }
73	
74	  return resolvedPath;
75	}
