30	  /**
31	   * Creates a new WorkspaceContext with the given initial directory and optional additional directories.
32	   * @param targetDir The initial working directory (usually cwd)
33	   * @param additionalDirectories Optional array of additional directories to include
34	   */
35	  constructor(
36	    readonly targetDir: string,
37	    additionalDirectories: string[] = [],
38	  ) {
39	    this.addDirectory(targetDir);
40	    this.addDirectories(additionalDirectories);
41	    this.initialDirectories = new Set(this.directories);
42	  }
43	
44	  /**
45	   * Registers a listener that is called when the workspace directories change.
46	   * @param listener The listener to call.
47	   * @returns A function to unsubscribe the listener.
48	   */
49	  onDirectoriesChanged(listener: () => void): Unsubscribe {
50	    this.onDirectoriesChangedListeners.add(listener);
51	    return () => {
52	      this.onDirectoriesChangedListeners.delete(listener);
53	    };
54	  }
