58	    for (const listener of [...this.onDirectoriesChangedListeners]) {
59	      try {
60	        listener();
61	      } catch (e) {
62	        // Don't let one listener break others.
63	        debugLogger.warn(
64	          `Error in WorkspaceContext listener: (${e instanceof Error ? e.message : String(e)})`,
65	        );
66	      }
67	    }
68	  }
