70	  /**
71	   * Adds a directory to the workspace.
72	   * @param directory The directory path to add (can be relative or absolute)
73	   * @param basePath Optional base path for resolving relative paths (defaults to cwd)
74	   * @throws Error if the directory cannot be added
75	   */
76	  addDirectory(directory: string): void {
77	    const result = this.addDirectories([directory]);
78	    if (result.failed.length > 0) {
79	      throw result.failed[0].error;
80	    }
81	  }
82	
83	  /**
84	   * Adds multiple directories to the workspace.
85	   * Emits a single change event if any directories are added.
86	   * @param directories The directory paths to add
87	   * @returns Object containing successfully added directories and failures
88	   */
89	  addDirectories(directories: string[]): AddDirectoriesResult {
90	    const result: AddDirectoriesResult = { added: [], failed: [] };
91	    let changed = false;
92	
93	    for (const directory of directories) {
94	      try {
95	        const resolved = this.resolveAndValidateDir(directory);
96	        if (!this.directories.has(resolved)) {
97	          this.directories.add(resolved);
