      llmContent,
      display: {
        name: READ_FILE_DISPLAY_NAME,
        description: this.getDescription(),
        resultSummary: displayResultSummary,
        result: { type: 'text', text: result.returnDisplay || '' },
      },
      returnDisplay: result.returnDisplay || '',
    };
  }
}

