import type { Config } from '../config/config.js';
import { WorkspaceContext } from './workspaceContext.js';
import {
  stripAtSignPrefix,
  resolveAndValidateWorkspacePath,
  correctPath,
} from './pathCorrector.js';

describe('scratch verify at-sign + boundary + symlink', () => {
  let tempDir: string;
  let rootDir: string;
  let config: Config;

  beforeEach(() => {
    tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'scratch-verify-'));
    rootDir = fs.realpathSync(path.join(tempDir, 'root'));
    fs.mkdirSync(rootDir, { recursive: true });
    fs.mkdirSync(path.join(rootDir, 'src'), { recursive: true });
    fs.writeFileSync(path.join(rootDir, 'src', 'index.ts'), 'hi');

    const ws = new WorkspaceContext(rootDir);
    config = {
      getTargetDir: () => rootDir,
      getWorkspaceContext: () => ws,
      validatePathAccess: (p: string) =>
        ws.isPathWithinWorkspace(p)
          ? null
          : `Path not in workspace: ${p}`,
    } as unknown as Config;
  });

  afterEach(() => {
    fs.rmSync(tempDir, { recursive: true, force: true });
  });

  it('strips @seg/ when first segment exists', () => {
    expect(stripAtSignPrefix('@src/index.ts', config)).toBe('src/index.ts');
  });

  it('does not strip @seg when first segment missing', () => {
    expect(stripAtSignPrefix('@nope/x.ts', config)).toBe('@nope/x.ts');
  });

  it('always strips @/ prefix', () => {
    expect(stripAtSignPrefix('@/etc/passwd', config)).toBe('/etc/passwd');
  });

  it('correctPath resolves @src/new.ts under existing dir', () => {
    const res = correctPath('@src/new.ts', config);
    expect(res.success).toBe(true);
    if (res.success) {
      expect(res.correctedPath).toBe(path.join(rootDir, 'src', 'new.ts'));
    }
  });

  it('resolveAndValidateWorkspacePath returns resolved path in workspace', () => {
    const p = resolveAndValidateWorkspacePath('@src/index.ts', config);
    expect(p).toBe(path.join(rootDir, 'src', 'index.ts'));
  });

  it('throws Path not in workspace for outside path', () => {
    expect(() =>
      resolveAndValidateWorkspacePath('/etc/passwd', config),
    ).toThrow(/Path not in workspace/);
  });

  it('throws Failed to resolve path for circular symlink', () => {
    const a = path.join(rootDir, 'a');
    const b = path.join(rootDir, 'b');
    fs.symlinkSync(b, a);
    fs.symlinkSync(a, b);
    expect(() => resolveAndValidateWorkspacePath('a', config)).toThrow(
      /Failed to resolve path/,
    );
  });
});
